per_hop.query:
SELECT ?university ?location ?campusCount WHERE {
  ?person a dbo:Person ;
          foaf:name "Richard J. Wood" ;
          dbo:academicAdvisor ?university .
  ?university a dbo:University ;
              dbo:location ?location ;
              dbo:numberOfCampuses ?campusCount .
  FILTER(CONTAINS(LCASE(STR(?location)), "connecticut"))
}
LIMIT 1

SELECT ?csupCampusCount WHERE {
  <http://dbpedia.org/resource/California_State_Polytechnic_University,_Pomona> dbo:numberOfCampuses ?csupCampusCount .
} 

ASK {
  ?university dbo:numberOfCampuses ?campusCount .
  <http://dbpedia.org/resource/California_State_Polytechnic_University,_Pomona> dbo:numberOfCampuses ?csupCampusCount .
  FILTER(?campusCount > ?csupCampusCount)
}
